package org.jlinalg.cli;
import java.io.IOException;
import java.nio.file.Path;
import java.util.*;
import org.jlinalg.embedding.PalantirMultiscale;
import static org.jlinalg.cli.Monocle3WorkflowRequest.*;
import static org.jlinalg.cli.CellPhoneDbWorkflowData.*;

/** Native checks of data-only original observations. KNN/eigensolver/trajectory fitting remain upstream. */
final class PalantirWorkflowAudit {
    private PalantirWorkflowAudit() { }
    static final class Meter {
        final long maximum;long used,numeric,identities,tsv;
        Meter(long maximum){this.maximum=maximum;}
        void add(long n)throws IOException {require(!Thread.currentThread().isInterrupted(),"Native audit cancelled; no partial batch admitted");require(n>=0&&n<=maximum-used,"Complete native audit operation capacity exceeded");used+=n;}
        void close(double actual,double expected,double atol,double rtol,String context)throws IOException {add(1);numeric++;require(Double.isFinite(actual)&&Double.isFinite(expected)&&(atol==0&&rtol==0?Double.doubleToRawLongBits(actual)==Double.doubleToRawLongBits(expected):Math.abs(actual-expected)<=atol+rtol*Math.abs(expected)),"Native numeric check differs: "+context+" actual="+actual+" expected="+expected);}
        void ids(List<String> actual,List<String> expected,String context)throws IOException {add(Math.max(actual.size(),expected.size())+1L);identities+=actual.size();require(actual.equals(expected),"Complete unchanged axes differ: "+context);}
    }
    record Series(List<String> index,double[] values) { }
    record Csr(List<Map<Integer,Double>> rows,int columns) {
        double get(int i,int j){return rows.get(i).getOrDefault(j,0.0);}
    }
    static Map<String,Object> read(Path path,PalantirWorkflowRequest.Request request)throws IOException {return PalantirWorkflowRuntime.read(path,(int)Math.min(67108864,request.outputBytes()));}
    static Series series(Object raw,PalantirWorkflowRequest.Request request)throws IOException {var s=object(raw);require(text(s.get("kind")).equals("series"),"Expected complete original Series");var index=strings(list(s.get("index")));var v=vector(s.get("data"),request.maximumMatrixCells());require(v.shape().size()==1&&v.size()==index.size(),"Original Series shape differs");double[] values=new double[v.size()];for(int i=0;i<values.length;i++)values[i]=v.number(i);return new Series(index,values);}
    static List<String> strings(List<?> raw)throws IOException {var result=new ArrayList<String>();for(Object item:raw)result.add(identity(item));return List.copyOf(result);}
    static List<String> labels(Object raw)throws IOException {
        if(raw instanceof List<?>)return strings(list(raw));var value=object(raw);String kind=text(value.get("kind"));if(kind.equals("index"))return strings(list(value.get("values")));var v=vector(raw,1000000);var result=new ArrayList<String>();for(int i=0;i<v.size();i++)result.add(text(v.value(i)));return List.copyOf(result);
    }
    static double[][] array(Object raw,PalantirWorkflowRequest.Request request)throws IOException {var v=vector(raw,request.maximumMatrixCells());require(v.shape().size()==2,"Expected complete numeric matrix");int n=v.shape().get(0),p=v.shape().get(1);double[][] result=new double[n][p];for(int i=0;i<n;i++)for(int j=0;j<p;j++)result[i][j]=v.number(i*p+j);return result;}
    static Csr csr(Object raw,PalantirWorkflowRequest.Request request,Meter meter)throws IOException {
        var s=object(raw);require(text(s.get("kind")).equals("csr"),"Expected data-only CSR");var shape=list(s.get("shape"));require(shape.size()==2,"CSR shape differs");int n=Math.toIntExact(integer(shape.get(0),0,request.maximumCells())),p=Math.toIntExact(integer(shape.get(1),0,request.maximumCells()));var values=vector(s.get("data"),request.maximumEdges());var indices=vector(s.get("indices"),request.maximumEdges());var ptr=vector(s.get("indptr"),(long)request.maximumCells()+1);require(values.shape().size()==1&&indices.shape().size()==1&&ptr.shape().size()==1&&values.size()==indices.size()&&ptr.size()==n+1&&ptr.number(0)==0&&ptr.number(n)==values.size(),"Complete CSR member shapes differ");var rows=new ArrayList<Map<Integer,Double>>();for(int i=0;i<n;i++){int a=Math.toIntExact(integer(ptr.value(i),0,values.size())),b=Math.toIntExact(integer(ptr.value(i+1),a,values.size()));var row=new LinkedHashMap<Integer,Double>();for(int k=a;k<b;k++){meter.add(1);int j=Math.toIntExact(integer(indices.value(k),0,p-1));double v=values.number(k);require(Double.isFinite(v)&&!row.containsKey(j),"Nonfinite/duplicate CSR entry; no repair");row.put(j,v);}rows.add(row);}return new Csr(rows,p);
    }
    static double distance(double[] a,double[] b,Meter meter)throws IOException {meter.add(a.length);double s=0;for(int j=0;j<a.length;j++){double d=a[j]-b[j];s+=d*d;}return Math.sqrt(s);}
    static void values(Frame actual,PalantirWorkflowInputs.Matrix expected,boolean columns,Meter meter,String context)throws IOException {meter.ids(actual.rowIds(),expected.cells(),context+" cells");require(actual.columns().size()==expected.columns().size(),"Component shape differs: "+context);if(columns)meter.ids(strings(actual.columns()),expected.columns(),context+" columns");for(int i=0;i<actual.rows();i++)for(int j=0;j<actual.columns().size();j++)meter.close(numeric(actual.value(i,j)),expected.values()[i][j],0,0,context);}
    static void compare(Csr actual,Csr expected,Meter meter,String context)throws IOException {require(actual.rows().size()==expected.rows().size()&&actual.columns()==expected.columns(),"Complete CSR shape differs: "+context);for(int i=0;i<actual.rows().size();i++){var keys=new HashSet<>(actual.rows().get(i).keySet());keys.addAll(expected.rows().get(i).keySet());for(int j:keys)meter.close(actual.get(i,j),expected.get(i,j),2e-12,2e-10,context);}}
    static Csr weights(Csr distances,double[] radii,Meter meter)throws IOException {var rows=new ArrayList<Map<Integer,Double>>();for(int i=0;i<distances.rows().size();i++){var row=new LinkedHashMap<Integer,Double>();for(var e:distances.rows().get(i).entrySet()){meter.add(1);if(e.getValue()!=0)row.put(e.getKey(),Math.exp(-e.getValue()/radii[i]));}rows.add(row);}return new Csr(rows,distances.columns());}
    static Csr normalized(Csr source,Meter meter)throws IOException {var rows=new ArrayList<Map<Integer,Double>>();for(var input:source.rows()){double sum=0;for(double x:input.values()){meter.add(1);sum+=x;}var row=new LinkedHashMap<Integer,Double>();for(var e:input.entrySet()){meter.add(1);row.put(e.getKey(),e.getValue()*(sum==0?0:1/sum));}rows.add(row);}return new Csr(rows,source.columns());}
    static PalantirWorkflowInputs.Matrix diffusion(Map<String,Object> specification,Path home,PalantirWorkflowInputs.Matrix input,PalantirWorkflowRequest.Request request,Meter meter)throws IOException {
        var options=object(specification.get("diffusion"));int n=input.cells().size(),knn=Math.toIntExact(integer(options.get("knn"),1,100000));var observation=read(home.resolve("observed-compute_kernel.json"),request);var local=object(observation.get("locals"));values(frame(local.get("data_df"),request.maximumMatrixCells()),input,text(object(specification.get("input")).get("interface")).equals("dataframe"),meter,"kernel input");require(integer(local.get("knn"),1,100000)==knn&&text(local.get("backend")).equals(text(options.get("kernel_backend"))),"Original kernel options differ");meter.close(numeric(local.get("alpha")),numeric(options.get("alpha")),0,0,"kernel alpha");var radii=vector(local.get("adaptive_std"),request.maximumCells());require(radii.size()==n,"Adaptive radius shape differs");double[] radius=new double[n];for(int i=0;i<n;i++)radius[i]=radii.number(i);Csr w;
        if(text(options.get("kernel_backend")).equals("scanpy")){
            var d=csr(local.get("kNN"),request,meter);require(d.rows().size()==n&&d.columns()==n,"KNN shape differs");int at=knn/3-1;for(int i=0;i<n;i++){double[] sorted=new double[d.rows().get(i).size()];int k=0;for(var e:d.rows().get(i).entrySet()){meter.close(e.getValue(),distance(input.values()[i],input.values()[e.getKey()],meter),2e-7,2e-6,"observed Scanpy edge distance");sorted[k++]=e.getValue();}Arrays.sort(sorted);int index=at<0?sorted.length+at:at;require(index>=0&&index<sorted.length,"Original adaptive order statistic unavailable");meter.close(radius[i],sorted[index],0,0,"Scanpy radius");}w=weights(d,radius,meter);
        }else{
            double[][] dist=array(local.get("dist"),request),ind=array(local.get("ind"),request);require(dist.length==n&&ind.length==n,"Exact KNN rows differ");var rows=new ArrayList<Map<Integer,Double>>();int at=Math.max(1,Math.min(knn/3,dist[0].length))-1;for(int i=0;i<n;i++){require(dist[i].length==ind[i].length,"Exact KNN shape differs");meter.close(radius[i],dist[i][at],0,0,"sklearn radius");var row=new LinkedHashMap<Integer,Double>();for(int k=0;k<dist[i].length;k++){int j=(int)ind[i][k];require(j>=0&&j<n&&ind[i][k]==j&&!row.containsKey(j),"Invalid/duplicate exact neighbor identity");meter.close(dist[i][k],distance(input.values()[i],input.values()[j],meter),2e-7,2e-6,"observed sklearn edge distance");row.put(j,Math.exp(-dist[i][k]/radius[i]));}rows.add(row);}w=new Csr(rows,n);
        }
        compare(csr(local.get("W"),request,meter),w,meter,"directed exponential kernel");var rows=new ArrayList<Map<Integer,Double>>();for(int i=0;i<n;i++)rows.add(new LinkedHashMap<>());for(int i=0;i<n;i++)for(var e:w.rows().get(i).entrySet()){meter.add(1);int j=e.getKey();rows.get(i).merge(j,e.getValue(),Double::sum);rows.get(j).merge(i,e.getValue(),Double::sum);}double alpha=numeric(options.get("alpha"));if(alpha>0){double[] degree=new double[n];for(int i=0;i<n;i++){for(double v:rows.get(i).values()){meter.add(1);degree[i]+=v;}if(degree[i]!=0)degree[i]=Math.pow(degree[i],-alpha);}for(int i=0;i<n;i++)for(var e:rows.get(i).entrySet()){meter.add(1);e.setValue(degree[i]*e.getValue()*degree[e.getKey()]);}}
        var expectedKernel=new Csr(rows,n);compare(csr(observation.get("returned"),request,meter),expectedKernel,meter,"symmetric density-normalized kernel");var result=read(home.resolve("diffusion-return.json"),request);compare(csr(result.get("kernel"),request,meter),expectedKernel,meter,"returned kernel");var transition=csr(result.get("T"),request,meter);compare(transition,normalized(expectedKernel,meter),meter,"diffusion row transition");var eigen=frame(result.get("EigenVectors"),request.maximumMatrixCells());meter.ids(eigen.rowIds(),input.cells(),"diffusion eigenvector cells");var eigenvalues=series(result.get("EigenValues"),request);require(eigen.columns().size()==eigenvalues.values().length&&eigen.columns().size()==integer(options.get("n_components"),1,4096),"Complete eigenpair shape differs");double[][] vectors=eigen.matrix();for(int c=0;c<eigen.columns().size();c++){double norm=0;for(int i=0;i<n;i++){meter.add(1);norm+=vectors[i][c]*vectors[i][c];double tv=0;for(var e:transition.rows().get(i).entrySet()){meter.add(1);tv+=e.getValue()*vectors[e.getKey()][c];}meter.close(tv,eigenvalues.values()[c]*vectors[i][c],2e-4,2e-4,"original ARPACK residual (source tol1e-4)");}meter.close(norm,1,2e-10,2e-10,"eigenvector unit norm");if(c>0)require(eigenvalues.values()[c-1]>=eigenvalues.values()[c],"Original descending eigenvalue order differs");}
        Integer count=options.get("n_eigs")==null?null:Math.toIntExact(integer(options.get("n_eigs"),2,4096));var scaled=PalantirMultiscale.scale(input.cells().toArray(String[]::new),vectors,eigenvalues.values(),count,new PalantirMultiscale.Limits(request.maximumCells(),request.maximumComponents(),request.maximumMatrixCells(),request.auditOperations()-meter.used));meter.add(scaled.operations());var coordinates=frame(read(home.resolve("multiscale-return.json"),request),request.maximumMatrixCells());var columns=new ArrayList<String>();for(int j=0;j<scaled.selectedComponents().length;j++)columns.add(Integer.toString(j));var matrix=new PalantirWorkflowInputs.Matrix(input.cells(),List.copyOf(columns),scaled.coordinates(),0);meter.ids(coordinates.rowIds(),input.cells(),"multiscale cells");meter.ids(strings(coordinates.columns()),columns,"multiscale columns");for(int i=0;i<n;i++)for(int j=0;j<columns.size();j++)meter.close(numeric(coordinates.value(i,j)),matrix.values()[i][j],0,0,"native Palantir multiscale");tsv(home.resolve("multiscale.tsv"),matrix.cells(),matrix.columns(),matrix.values(),request,meter);return matrix;
    }
    static double entropy(double[] probabilities)throws IOException {double sum=0;for(double v:probabilities){require(Double.isFinite(v)&&v>=0,"Invalid original preclip probability");sum+=v;}if(probabilities.length==0)return 0;require(sum>0,"Zero total preclip fate probability");double value=0;for(double v:probabilities)if(v>0){double p=v/sum;value-=p*Math.log(p);}return value;}
    static void tsv(Path path,List<String> cells,List<String> columns,double[][] values,PalantirWorkflowRequest.Request request,Meter meter)throws IOException {
        try(var rows=new CellPhoneDbWorkflowInputs.Rows(path,'\t',request.outputBytes())){var header=rows.next();var expected=new ArrayList<String>();expected.add("cell_id");expected.addAll(columns);require(header!=null,"Missing TSV header");meter.ids(header,expected,"complete TSV header");for(int i=0;i<cells.size();i++){var row=rows.next();require(row!=null&&row.size()==columns.size()+1&&row.get(0).equals(cells.get(i)),"TSV cells/shape/order differ");for(int j=0;j<columns.size();j++){double value;try{value=Double.parseDouble(row.get(j+1));}catch(NumberFormatException failure){throw new IOException("Invalid original TSV numeric token",failure);}meter.close(value,values[i][j],0,0,"TSV round-trip");meter.tsv++;}}require(rows.next()==null,"Unexpected extra TSV rows");}
    }
    static Map<String,Object> analyze(Map<String,Object> specification,Path home,PalantirWorkflowInputs.Matrix input,PalantirWorkflowRequest.Request request,List<String> warnings,Meter meter)throws IOException {
        String id=text(specification.get("id")),method=text(specification.get("method"));values(frame(read(home.resolve("source-input.json"),request),request.maximumMatrixCells()),input,true,meter,"original input");var observer=read(home.resolve("observer.json"),request);require(Boolean.TRUE.equals(observer.get("namespace_functions_unchanged"))&&Boolean.TRUE.equals(observer.get("code_objects_unchanged")),"Original namespace function/code identities changed");var result=new LinkedHashMap<String,Object>();result.put("id",id);result.put("method",method);result.put("cells",input.cells().size());result.put("independent_trajectory_refit",false);if(!method.equals("trajectory"))input=diffusion(specification,home,input,request,meter);if(method.equals("diffusion")){result.put("multiscale_components",input.columns().size());return result;}
        var options=object(specification.get("trajectory"));var pseudotimeObservation=read(home.resolve("observed-_compute_pseudotime.json"),request);var local=object(pseudotimeObservation.get("locals"));var data=frame(local.get("data"),request.maximumMatrixCells());meter.ids(data.rowIds(),input.cells(),"trajectory input cells");require(data.columns().size()==input.columns().size()&&!data.columns().isEmpty(),"Trajectory coordinate shape differs");double[][] scaled=data.matrix();boolean scaling=bool(options.get("scale_components"));for(int j=0;j<input.columns().size();j++){double minimum=Double.POSITIVE_INFINITY,maximum=Double.NEGATIVE_INFINITY;for(double[] row:input.values()){meter.add(1);minimum=Math.min(minimum,row[j]);maximum=Math.max(maximum,row[j]);}double range=maximum-minimum,scale=1/(range<10*Math.ulp(1.0)?1:range);for(int i=0;i<scaled.length;i++)meter.close(scaled[i][j],scaling?input.values()[i][j]*scale-minimum*scale:input.values()[i][j],2e-12,2e-10,"native minmax scale");}
        var returned=read(home.resolve("returned.json"),request);var before=read(home.resolve("before-result-clipping.json"),request);var pt=series(returned.get("pseudotime"),request);var ent=series(returned.get("entropy"),request);var prePt=series(before.get("pseudotime"),request);var preEnt=series(before.get("entropy"),request);var pre=frame(before.get("branch_probs"),request.maximumMatrixCells());var post=frame(returned.get("branch_probs"),request.maximumMatrixCells());meter.ids(pt.index(),input.cells(),"returned pseudotime cells");meter.ids(ent.index(),input.cells(),"returned entropy cells");meter.ids(pre.rowIds(),input.cells(),"preclip fate cells");meter.ids(post.rowIds(),input.cells(),"postclip fate cells");meter.ids(prePt.index(),pt.index(),"preclip pseudotime");meter.ids(preEnt.index(),ent.index(),"preclip entropy");var waypoints=labels(returned.get("waypoints"));meter.ids(labels(before.get("waypoints")),waypoints,"preclip waypoints");require(!waypoints.isEmpty()&&waypoints.size()<=request.maximumWaypoints()&&new HashSet<>(waypoints).size()==waypoints.size()&&input.cells().containsAll(waypoints),"Incomplete/duplicate/oversized waypoint identities");
        var pReturn=list(pseudotimeObservation.get("returned"));require(pReturn.size()==2,"Pseudotime return family differs");var observedPt=series(pReturn.get(0),request);meter.ids(observedPt.index(),pt.index(),"observed pseudotime order");var weights=frame(pReturn.get(1),request.maximumMatrixCells());meter.ids(weights.rowIds(),waypoints,"weight waypoint order");meter.ids(strings(weights.columns()),input.cells(),"weight cell order");var distances=array(local.get("D_vals"),request);require(distances.length==weights.rows(),"Shortest-path distance shape differs");double sdv=numeric(local.get("sdv"));require(Double.isFinite(sdv)&&sdv>0,"Original distance bandwidth invalid");for(int i=0;i<input.cells().size();i++){double largest=Double.NEGATIVE_INFINITY;for(int w=0;w<waypoints.size();w++){meter.add(1);require(distances[w].length==input.cells().size()&&Double.isFinite(distances[w][i])&&distances[w][i]>=0,"Shortest-path observations invalid");double z=distances[w][i]/sdv;largest=Math.max(largest,-.5*z*z);}double total=0;double[] expected=new double[waypoints.size()];for(int w=0;w<expected.length;w++){meter.add(1);double z=distances[w][i]/sdv;expected[w]=Math.exp(-.5*z*z-(request.edition().equals("1.4.6")?largest:0));total+=expected[w];}for(int w=0;w<expected.length;w++)meter.close(numeric(weights.value(w,i)),expected[w]/total,2e-12,2e-10,"original version-specific Gaussian/softmax weight");}
        List<String> starts=request.edition().equals("1.4.4")?List.of(text(local.get("start_cell"))):labels(local.get("start_cells"));var early=PalantirWorkflowRequest.identities(options.get("early_cells"),64);if(bool(options.get("use_early_cell_as_start")))meter.ids(starts,early,"explicit early/start cells");else{for(String start:starts)require(input.cells().contains(start),"Observed boundary root absent");warnings.add(id+": original boundary-root selection retained with Python hash seed; native audit checks inputs/outputs but does not independently repeat boundary tie ordering.");}require(waypoints.containsAll(starts),"Start cells missing from waypoints");
        var differential=read(home.resolve("observed-_differentiation_entropy.json"),request);var dlocal=object(differential.get("locals"));var bp=frame(list(differential.get("returned")).get(1),request.maximumMatrixCells());require(bp.rows()==waypoints.size()&&new HashSet<>(bp.rowIds()).equals(new HashSet<>(waypoints)),"Complete waypoint fate row family differs");var fateCells=strings(bp.columns());require(new HashSet<>(fateCells).size()==fateCells.size()&&waypoints.containsAll(fateCells),"Original fate columns are not unique waypoint cell IDs");if(options.get("terminal_states")!=null){var specified=new HashSet<String>();for(Object item:list(options.get("terminal_states")))specified.add(text(object(item).get("cell")));require(specified.equals(new HashSet<>(fateCells)),"Requested terminal family partially dropped or changed");}
        var expectedLabels=new ArrayList<>(fateCells);if(text(object(specification.get("input")).get("interface")).equals("anndata")&&options.get("terminal_states")!=null){var mapping=new HashMap<String,String>();for(Object item:list(options.get("terminal_states"))){var t=object(item);if(t.containsKey("annotation"))mapping.put(text(t.get("cell")),text(t.get("annotation")));}if(!mapping.isEmpty())for(int j=0;j<expectedLabels.size();j++)expectedLabels.set(j,mapping.get(fateCells.get(j)));}meter.ids(strings(pre.columns()),fateCells,"preclip fate cell columns");meter.ids(strings(post.columns()),expectedLabels,"original interface-specific fate labels");
        var markov=read(home.resolve("observed-_construct_markov_chain.json"),request);var ml=object(markov.get("locals"));var wpData=frame(ml.get("wp_data"),request.maximumMatrixCells());meter.ids(wpData.rowIds(),waypoints,"Markov waypoint cells");for(int w=0;w<waypoints.size();w++){int i=input.cells().indexOf(waypoints.get(w));for(int c=0;c<input.columns().size();c++)meter.close(numeric(wpData.value(w,c)),scaled[i][c],0,0,"Markov waypoint coordinates");}var transition=csr(markov.get("returned"),request,meter);require(transition.rows().size()==waypoints.size()&&transition.columns()==waypoints.size(),"Markov transition shape differs");var idx=array(ml.get("ind"),request);var dist=array(ml.get("dist"),request);var radius=vector(ml.get("adaptive_std"),request.maximumWaypoints());var mpt=series(ml.get("pseudotime"),request);meter.ids(mpt.index(),pt.index(),"Markov pseudotime order");var wpMatrix=wpData.matrix();var markovRows=new ArrayList<Map<Integer,Double>>();int adaptive=Math.min(Math.toIntExact(integer(options.get("knn"),1,100000))/3-1,30);for(int w=0;w<waypoints.size();w++){require(idx[w].length==dist[w].length,"Markov neighbor matrix shape differs");int at=adaptive<0?dist[w].length+adaptive:adaptive;meter.close(radius.number(w),dist[w][at],0,0,"Markov adaptive radius");var row=new LinkedHashMap<Integer,Double>();int source=input.cells().indexOf(waypoints.get(w));for(int k=0;k<idx[w].length;k++){int j=(int)idx[w][k];require(j>=0&&j<waypoints.size()&&idx[w][k]==j,"Invalid Markov neighbor identity");meter.close(dist[w][k],distance(wpMatrix[w],wpMatrix[j],meter),2e-7,2e-6,"Markov neighbor distance");int target=input.cells().indexOf(waypoints.get(j));if(mpt.values()[target]>=mpt.values()[source]-radius.number(w)&&dist[w][k]!=0){double z=dist[w][k]*dist[w][k];row.put(j,Math.exp(-z/(radius.number(w)*radius.number(w))*.5-z/(radius.number(j)*radius.number(j))*.5));}}markovRows.add(row);}compare(transition,normalized(new Csr(markovRows,waypoints.size()),meter),meter,"native directed Markov weights");
        var bpRows=bp.rowIds();var bpPositions=new HashMap<String,Integer>();for(int r=0;r<bpRows.size();r++)require(bpPositions.put(bpRows.get(r),r)==null,"Duplicate waypoint fate row identity");for(int w=0;w<waypoints.size();w++){int b=bpPositions.get(waypoints.get(w));for(int f=0;f<fateCells.size();f++){double actual=numeric(bp.value(b,f));if(fateCells.contains(waypoints.get(w)))meter.close(actual,waypoints.get(w).equals(fateCells.get(f))?1:0,0,0,"terminal one-hot");else{double expected=0;for(var e:transition.rows().get(w).entrySet()){meter.add(1);expected+=e.getValue()*numeric(bp.value(bpPositions.get(waypoints.get(e.getKey())),f));}meter.close(actual,expected,2e-7,2e-6,"absorbing Markov probability residual");}}}
        if(fateCells.isEmpty()){require(text(options.get("empty_fates")).equals("retain-pseudotime-only"),"Original detected no fate states. Explicit empty_fates=fail rejects whole batch; supply scientifically justified terminals or explicitly retain pseudotime only in NEW output");warnings.add(id+": NO FATE PROBABILITIES. Original source returned zero fate columns; explicit policy retains pseudotime only. Entropy zero is not evidence of a differentiated state.");}
        double minimum=Double.POSITIVE_INFINITY,maximum=Double.NEGATIVE_INFINITY;long clipped=0,lowMass=0;double[][] ptx=new double[input.cells().size()][2],postValues=post.matrix();for(int i=0;i<input.cells().size();i++){meter.close(pt.values()[i],prePt.values()[i],0,0,"pre/post pseudotime");meter.close(pt.values()[i],observedPt.values()[i],0,0,"observed pseudotime");meter.close(mpt.values()[i],pt.values()[i],0,0,"Markov pseudotime");meter.close(ent.values()[i],preEnt.values()[i],0,0,"pre/post entropy");minimum=Math.min(minimum,pt.values()[i]);maximum=Math.max(maximum,pt.values()[i]);double[] probabilities=new double[fateCells.size()];double mass=0;for(int f=0;f<fateCells.size();f++){double projected=0;for(int w=0;w<waypoints.size();w++){meter.add(1);projected+=numeric(weights.value(w,i))*numeric(bp.value(bpPositions.get(waypoints.get(w)),f));}probabilities[f]=numeric(pre.value(i,f));meter.close(probabilities[f],projected,2e-11,2e-9,"waypoint fate projection");double expected=probabilities[f]<.01?0:probabilities[f];if(probabilities[f]<.01)clipped++;meter.close(postValues[i][f],expected,0,0,"original below0.01 clipping");mass+=postValues[i][f];}meter.close(ent.values()[i],entropy(probabilities),2e-12,2e-10,"entropy from preclip probabilities");if(mass<1-1e-10&&!fateCells.isEmpty())lowMass++;ptx[i][0]=pt.values()[i];ptx[i][1]=ent.values()[i];}meter.close(minimum,0,2e-12,0,"pseudotime min");meter.close(maximum,1,2e-12,0,"pseudotime max");tsv(home.resolve("pseudotime.tsv"),input.cells(),List.of("pseudotime","entropy"),ptx,request,meter);tsv(home.resolve("fate-probabilities.tsv"),input.cells(),expectedLabels,postValues,request,meter);
        warnings.add(id+": original clipped "+clipped+" probability states below0.01; "+lowMass+" returned rows have total mass below1. Entropy uses the preclip distribution. Do not renormalize silently. Waypoint count is "+waypoints.size()+" after original sampling/unions, not necessarily the requested count.");result.put("waypoints",waypoints.size());result.put("fate_columns",fateCells.size());result.put("clipped_probability_states",clipped);result.put("postclip_rows_below_unit_mass",lowMass);result.put("empty_fate_policy",text(options.get("empty_fates")));return result;
    }
}
